-- PostgreSQL starter schema for EV PAL synthetic-data ingestion.
CREATE TABLE vehicles (vehicle_id TEXT PRIMARY KEY, manufacturer TEXT NOT NULL, model TEXT NOT NULL, variant TEXT NOT NULL, vehicle_category TEXT, synthetic BOOLEAN NOT NULL DEFAULT TRUE, source_type TEXT NOT NULL DEFAULT 'synthetic', generated_at TIMESTAMPTZ, generation_method TEXT, source_reference TEXT);
CREATE TABLE batteries (battery_id TEXT PRIMARY KEY, vehicle_id TEXT NOT NULL REFERENCES vehicles(vehicle_id), chemistry TEXT, battery_capacity_kwh NUMERIC, usable_capacity_kwh NUMERIC, synthetic BOOLEAN NOT NULL DEFAULT TRUE, source_type TEXT NOT NULL DEFAULT 'synthetic', generated_at TIMESTAMPTZ, generation_method TEXT, source_reference TEXT);
CREATE TABLE soh_observations (observation_id TEXT PRIMARY KEY, battery_instance_id TEXT NOT NULL, vehicle_id TEXT NOT NULL REFERENCES vehicles(vehicle_id), soh_percent NUMERIC CHECK (soh_percent BETWEEN 0 AND 100), estimated_capacity_kwh NUMERIC, synthetic BOOLEAN NOT NULL DEFAULT TRUE, source_type TEXT NOT NULL DEFAULT 'synthetic', generated_at TIMESTAMPTZ, generation_method TEXT, source_reference TEXT);
CREATE TABLE charging_sessions (session_id TEXT PRIMARY KEY, vehicle_id TEXT NOT NULL REFERENCES vehicles(vehicle_id), timestamp TIMESTAMPTZ, charging_type TEXT, energy_delivered_kwh NUMERIC, synthetic BOOLEAN NOT NULL DEFAULT TRUE, source_type TEXT NOT NULL DEFAULT 'synthetic', generated_at TIMESTAMPTZ, generation_method TEXT, source_reference TEXT);
CREATE INDEX idx_soh_vehicle ON soh_observations(vehicle_id);
CREATE INDEX idx_sessions_vehicle_time ON charging_sessions(vehicle_id, timestamp);
